const UI_ENTRIES=Object.entries(UI_COPY).sort((a,b)=>b[0].length-a[0].length);
const textSources=new WeakMap(),attributeSources=new WeakMap();
function translateUiText(text,lang=uiLanguage){if(lang==='ru')return text;const index=lang==='kk'?0:1;let result=text;
 for(const [source,values]of UI_ENTRIES)if(result.includes(source))result=result.split(source).join(values[index]);
 result=result.replace(/Выбрано:\s*(\d+)/g,lang==='kk'?'Таңдалды: $1':'Selected: $1').replace(/(\d+) заведени[ейя]+/g,lang==='kk'?'$1 орын':'$1 venues').replace(/(\d+) заведение/g,lang==='kk'?'$1 орын':'$1 venue');
 if(lang==='en')result=result.replace(/КУХНЯ/g,'CUISINE').replace(/Количество гостей · максимум/g,'Guests · maximum').replace(/Создать заказ ·/g,'Place order ·').replace(/мин/g,'min');
 else result=result.replace(/КУХНЯ/g,'АСХАНАСЫ').replace(/Количество гостей · максимум/g,'Қонақтар саны · ең көбі').replace(/Создать заказ ·/g,'Тапсырыс беру ·');
 return result;
}
function languageSwitcher(){return `<div class="language-switch" role="group" aria-label="Тіл / Язык / Language" data-i18n-skip style="--lang-index:${UI_LANGS.indexOf(uiLanguage)}"><span class="language-thumb" aria-hidden="true"></span>${UI_LANGS.map((lang,i)=>`<button type="button" aria-label="${['Қазақша','Русский','English'][i]}" aria-pressed="${uiLanguage===lang}" onclick="switchLanguage('${lang}')">${['ҚАЗ','РУС','ENG'][i]}</button>`).join('')}</div>`}
function applyUiLanguage(){document.documentElement.lang=uiLanguage;document.title=uiLanguage==='kk'?'Dayin — Атыраудағы мейрамханалар':uiLanguage==='en'?'Dayin — Restaurants in Atyrau':'Dayin — Рестораны Атырау';
 const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){if(node.parentElement?.closest('script,style,[data-i18n-skip],.dish-info h3,.dish-info p,.cardtitle,.owner-name,.admin-venue strong,input,textarea'))continue;const previous=textSources.get(node),source=previous&&node.nodeValue===previous.translated?previous.source:node.nodeValue;const translated=translateUiText(source);textSources.set(node,{source,translated});if(node.nodeValue!==translated)node.nodeValue=translated}
 document.querySelectorAll('[placeholder],[aria-label],[title],[alt]').forEach(element=>{if(element.closest('[data-i18n-skip]'))return;const saved=attributeSources.get(element)||{};for(const attribute of ['placeholder','aria-label','title','alt'])if(element.hasAttribute(attribute)){const value=element.getAttribute(attribute),old=saved[attribute],source=old&&old.translated===value?old.source:value,translated=translateUiText(source);saved[attribute]={source,translated};if(value!==translated)element.setAttribute(attribute,translated)}attributeSources.set(element,saved)});
 document.querySelectorAll('.language-switch').forEach(control=>{control.style.setProperty('--lang-index',String(UI_LANGS.indexOf(uiLanguage)));control.querySelectorAll('button').forEach((button,i)=>button.setAttribute('aria-pressed',String(UI_LANGS[i]===uiLanguage)))})
}
function switchLanguage(lang){if(!UI_LANGS.includes(lang))return;uiLanguage=lang;localStorage.setItem('dayin-language',lang);applyUiLanguage()}
if(typeof MutationObserver!=='undefined'){let pending=false;new MutationObserver(()=>{if(pending)return;pending=true;queueMicrotask(()=>{pending=false;applyUiLanguage()})}).observe(document.body,{childList:true,subtree:true,characterData:true});queueMicrotask(applyUiLanguage)}
